/** Curated content. Source of truth since phase 2. */
export interface QuranReading {s:number;f:number;t:number;n:string;sum:string;mz:string;q:string;k:string}
export const QPLAN: QuranReading[] = [
{s:1,f:1,t:7,n:"Al-Fatiha, the whole Book in seven verses",sum:"Praise belongs to Allah, Lord of all worlds; He is Merciful and Master of the Day of Judgement; we worship and seek help from Him alone; and we ask for the straight path of those He favoured, not of those under anger or astray.",mz:"Al-Mizan treats the basmala as a verse of every surah and reads 'al-hamd' with its definite article as all praise, whoever appears to receive it. Tabataba'i notes the shift from speaking about Allah to addressing Him at 'You alone we worship', the move from knowledge to presence. He reads the straight path through 4:69 as the path of the prophets, the truthful, the martyrs and the righteous, and explains 'sirat' as the single road that gathers all the smaller 'subul'.",q:"When I say 'You alone we worship', whom else do I quietly serve?",k:"Al-Fatiha is the prayer we say in every salah: Allah, show us the right road."},
{s:2,f:1,t:5,n:"Al-Baqarah 1–5, the Book and the God-conscious",sum:"The Book without doubt is guidance for the muttaqin: those who believe in the unseen, keep prayer, spend from what they are given, believe in what was sent down before and after, and are certain of the Hereafter. They are the guided and the successful.",mz:"Tabataba'i distinguishes two guidances: showing the way, which the Quran offers to all, and bringing to the goal, which it gives to the muttaqin, so the verse is not circular. He reads 'the unseen' as including Allah, His signs and the Hereafter, and connects 'certainty' with the final verses of the surah on the believers' trust.",q:"Which of the five qualities is weakest in me this week?",k:"The Quran is a guide for people who are careful and trust Allah even when they cannot see Him."},
{s:2,f:30,t:39,n:"Adam, the names, and the first repentance",sum:"Allah tells the angels He will place a vicegerent on earth; He teaches Adam the names; the angels bow and Iblis refuses in pride; Adam and his wife slip at the tree, receive words of repentance, and are forgiven; guidance will come, and whoever follows it has no fear.",mz:"Al-Mizan reads the 'names' as realities that Adam was made to know, not vocabulary, which is why the angels could not learn them by being told. Khilafah is explained as representing Allah's attributes on earth, a station belonging to humankind as such. The descent is not a punishment that cancels the station; Tabataba'i stresses that Adam's slip preceded the law and that repentance restored him.",q:"What have I been made to know that I have not yet lived?",k:"Adam made a mistake, said sorry at once and was forgiven. Iblis was proud and would not."},
{s:2,f:124,t:129,n:"Ibrahim's imamate and the building of the House",sum:"Allah tested Ibrahim with words and he fulfilled them; He said: I am making you an imam for mankind. Ibrahim asked for his descendants; the answer: My covenant does not reach the wrongdoers. Then Ibrahim and Isma'il raise the foundations of the House and pray for a messenger from among them.",mz:"One of al-Mizan's best-known discussions: imamate is given to Ibrahim after prophethood and after trials, so it is a station above prophethood, a guiding by Allah's command that brings people to the goal. Because the covenant excludes wrongdoers, Tabataba'i argues the imam must be protected from wrongdoing, and he extends the reasoning to the Imams of the Household.",q:"What trial, completed, would make me trustworthy with more?",k:"Ibrahim passed every test, so Allah made him a leader, and he built the Ka'bah with his son."},
{s:2,f:153,t:157,n:"Patience, prayer and the words of loss",sum:"Seek help in patience and prayer; Allah is with the patient. Those killed in His way are alive. You will be tested with fear, hunger and loss of wealth, lives and fruits; the patient say: we belong to Allah and to Him we return. On them are blessings and mercy, and they are the guided.",mz:"Tabataba'i reads 'Allah is with the patient' as a special companionship beyond His general presence. He explains 'inna lillah' as the statement of ownership that dissolves grief: what belongs to Him cannot truly be lost. Hunger is listed among the tests, a reminder that the fast is a rehearsal of this verse.",q:"What loss am I still treating as mine?",k:"When something is hard or lost, patient people say: we belong to Allah. Then they feel strong."},
{s:2,f:183,t:187,n:"The verses of fasting",sum:"Fasting is prescribed as for those before you, so you may attain taqwa; counted days, with exemptions; Ramadan is the month the Quran was sent down; Allah wants ease; when My servants ask about Me, I am near and answer the caller; eating and drinking until dawn, then the fast to night.",mz:"Al-Mizan draws out the purpose clause: taqwa, not hardship, is the aim, and the exemptions prove that ease is intended. Tabataba'i pauses on 2:186, placed in the middle of the fasting laws, where Allah answers without a messenger between, 'I am near', and reads it as the inner meaning of the whole month.",q:"Is my fast producing taqwa, or only hunger?",k:"We fast in Ramadan so our hearts get careful and close to Allah, who says: I am near."},
{s:2,f:255,t:257,n:"Ayat al-Kursi and the rope that does not break",sum:"Allah, there is no god but He, the Living, the Sustainer; no sleep touches Him; no intercession but by His leave; His Kursi encompasses the heavens and the earth. No compulsion in religion; whoever rejects false gods and believes in Allah has grasped the firmest handhold. Allah is the guardian of the believers, bringing them from darkness into light.",mz:"Tabataba'i reads al-Hayy al-Qayyum as the two names from which all others flow: life and self-subsistence that sustains everything else. He explains the Kursi as the domain of His knowledge and rule, not a seat. On 'no compulsion', he notes that faith is an inner conviction that force cannot produce, and reads 'darkness into light' as the plural many errors against the single truth.",q:"What false god did I reject today, and what did I hold instead?",k:"Ayat al-Kursi says Allah never sleeps and looks after everything. Say it before bed."},
{s:2,f:284,t:286,n:"The closing prayer of al-Baqarah",sum:"To Allah belongs what is in the heavens and earth; the Messenger and the believers believe; we hear and obey. Allah burdens no soul beyond its capacity; each has what it earned. Our Lord, do not blame us for forgetting; do not lay on us what we cannot bear; pardon, forgive, have mercy; You are our Master.",mz:"Al-Mizan reads the ending as the believers' response to the whole surah, mirroring its opening description of the muttaqin. Tabataba'i discusses 'no soul is burdened beyond its capacity' as a statement about the law itself, which is built within human capacity, so the following prayer asks for mercy within the law, not exemption from it.",q:"Which of my burdens did I pick up myself?",k:"Allah never gives a test too big for you. This is a prayer to say at night."},
{s:3,f:7,t:9,n:"Clear and ambiguous verses, and ta'wil",sum:"Some verses are decisive, the mother of the Book, and others are ambiguous; those with deviation chase the ambiguous seeking discord and its ta'wil, but none knows its ta'wil except Allah; those firmly rooted in knowledge say: we believe in it, all is from our Lord.",mz:"A central passage for al-Mizan's method. Tabataba'i argues that ta'wil is not a hidden meaning of words but the reality the verse refers back to, and that the ambiguous is returned to the decisive for understanding, Quran explaining Quran. He reads 'those firmly rooted in knowledge' as joined to Allah in knowing the ta'wil, while their 'we believe' expresses submission, and identifies them first with the Prophet and his Household.",q:"Where do I prefer an ambiguity because it lets me do what I want?",k:"Some verses are very clear and some are deep. We understand the deep ones by using the clear ones."},
{s:3,f:102,t:105,n:"Hold the rope together",sum:"Fear Allah as He should be feared and do not die except as Muslims; hold fast to the rope of Allah all together and do not divide; remember His favour when you were enemies and He joined your hearts; let there be a community calling to good; do not be like those who divided after clear proofs.",mz:"Tabataba'i identifies the rope with the Quran and the covenant it carries, and treats the joining of hearts as a divine act, not a social achievement. He reads the command as addressed to the community as a body: unity is a duty of the whole, and division after proof is the specific failure of earlier nations the surah warns against.",q:"Which rope do I grip when the family argues?",k:"Muslims should hold on to Allah's rope together, like a team, and not split up."},
{s:3,f:133,t:136,n:"The God-conscious: anger, pardon, and the return",sum:"Race to forgiveness and a garden as wide as the heavens, prepared for the God-conscious: who spend in ease and hardship, restrain anger, pardon people, and when they commit an indecency or wrong themselves remember Allah and seek forgiveness, and do not persist knowingly.",mz:"Al-Mizan reads the sequence as a ladder: spending, then restraining anger, then pardon, then ihsan, each harder than the last. Tabataba'i notes that the muttaqin are not described as sinless; their mark is that they do not persist, and that remembering Allah is placed as the hinge between the sin and the return.",q:"What am I persisting in because I have stopped remembering?",k:"Allah loves people who control their anger, forgive, and say sorry quickly when they slip."},
{s:3,f:159,t:160,n:"Gentleness, consultation, trust",sum:"By Allah's mercy you were gentle with them; had you been harsh they would have dispersed; so pardon them, ask forgiveness for them, and consult them; when you have decided, rely on Allah. If Allah helps you none can overcome you.",mz:"Tabataba'i draws attention to the order: pardon, then prayer for them, then consultation, then decision, then trust. Consultation is commanded even for the Prophet, as a method of binding hearts, while the decision remains with the one who leads, and tawakkul follows resolve rather than replacing it.",q:"Whom did I decide for today without asking?",k:"The Prophet was gentle and asked people what they thought. Then he decided and trusted Allah."},
{s:4,f:1,t:1,n:"One soul, and the womb",sum:"O mankind, fear your Lord who created you from one soul and from it its mate, and from the two spread many men and women; fear Allah by whom you ask one another, and the wombs. Allah watches over you.",mz:"Al-Mizan reads the verse as the foundation of the surah's laws on family: all humans share one origin, so rights follow from kinship rather than rank. Tabataba'i discusses 'one soul' as Adam, and treats 'the wombs' as a reminder that ties of kinship are placed beside taqwa itself.",q:"Which relative have I let the tie go slack with?",k:"All people come from one family, so we treat everyone like relatives."},
{s:4,f:36,t:36,n:"The verse of rights",sum:"Worship Allah and associate nothing with Him; do good to parents, relatives, orphans, the needy, the near neighbour, the far neighbour, the companion at your side, the traveller, and those your right hands possess. Allah does not love the proud and boastful.",mz:"Tabataba'i reads the list as circles of ihsan widening from parents outward, with tawhid as the root from which the duties grow. He notes the closing clause on pride: the vice that denies others their due is named as the opposite of ihsan.",q:"Who is the 'companion at my side' today, and how did I treat them?",k:"Be kind to parents, family, neighbours, and anyone near you. Allah does not like show-offs."},
{s:4,f:58,t:59,n:"Trusts, justice, and those in authority",sum:"Allah commands you to return trusts to their owners and to judge with justice; obey Allah, obey the Messenger, and those in authority among you; if you dispute, refer it to Allah and the Messenger.",mz:"Al-Mizan's discussion is well known: because obedience to 'those in authority' is joined to obedience to the Messenger without a condition, Tabataba'i argues they must be protected from error, and identifies them with the Imams of the Household; he notes that disputes are referred to Allah and the Messenger, not to them, since they themselves refer to the Book and Sunna. Other schools read the verse of rulers generally; the Quran's own words are what both must return to.",q:"Whom do I obey without checking, and is that trust placed well?",k:"Give back what you are trusted with, be fair, and follow good guides who follow Allah."},
{s:4,f:135,t:135,n:"Justice even against yourself",sum:"O you who believe, be upholders of justice, witnesses for Allah, even against yourselves or parents or relatives, rich or poor; Allah is closer to both. Do not follow desire lest you swerve; if you distort or refuse, Allah is aware.",mz:"Tabataba'i reads 'witnesses for Allah' as the motive that keeps testimony straight when the self, the parents or wealth pull it. Justice is presented as a standing quality (qawwamin), not an occasional act, and desire is named as the specific force that bends it.",q:"When did I last tell the truth against my own interest?",k:"Be fair even when it is hard, even if it means saying something true about yourself."},
{s:5,f:1,t:3,n:"Fulfil the contracts; the religion completed",sum:"Fulfil your contracts; the lawful and unlawful among animals; do not violate the rites; cooperate in righteousness and piety, not in sin and aggression; forbidden foods listed; this day I have perfected your religion for you and completed My favour and chosen Islam as your religion.",mz:"Al-Mizan reads 'this day' as a specific day on which the religion was completed by a specific act, and argues from the context and the narrations for the day of Ghadir and the announcement of 'Ali's wilayah; Tabataba'i discusses at length why the sentence sits inside a list of food laws. Readers of other schools place it at the farewell pilgrimage; the passage repays reading with both views open.",q:"What contract have I made with myself that I have not fulfilled?",k:"Keep your promises, eat only good food, and help each other do good."},
{s:5,f:54,t:56,n:"The verse of wilayah",sum:"Allah will bring a people He loves and who love Him, humble to believers, firm against disbelievers. Your guardian is only Allah, His Messenger, and those who believe, who establish prayer and give zakat while bowing. Whoever takes Allah, His Messenger and the believers as guardians: the party of Allah will prevail.",mz:"Tabataba'i argues that 'wali' here means authority and guardianship, not mere friendship, because of the restrictive 'only' and the parallel with Allah and the Messenger, and reads 'who give zakat while bowing' as referring to 'Ali's giving of his ring in prayer, as narrated in both Shi'a and many Sunni sources. The verse is the Quranic anchor of the Shi'a understanding of imamate.",q:"Whose guardianship do I actually live under: Allah's, or my habits'?",k:"Allah, the Prophet and the believers who pray and give are the ones who look after us."},
{s:6,f:74,t:83,n:"Ibrahim's argument from the stars",sum:"Ibrahim confronts his father's idols; he is shown the kingdom of the heavens; the star, the moon, the sun each set, and he says: I do not love what sets. He turns his face to the Originator of the heavens and earth, and argues with his people without fear.",mz:"Al-Mizan reads the sequence not as Ibrahim's own doubt but as a demonstration conducted for his people, moving from the lesser light to the greater and rejecting each by the same proof: what sets cannot be a lord. Tabataba'i treats 'I do not love what sets' as the spiritual centre: worship is love, and love cannot rest on what perishes.",q:"What do I love that sets?",k:"Ibrahim saw the stars and moon disappear and said: I only love the One who never goes away."},
{s:6,f:151,t:153,n:"The ten commandments of the Quran",sum:"Come, I will recite what your Lord forbade: associate nothing with Him; be good to parents; do not kill children from poverty; do not approach indecency; do not kill a soul unjustly; do not touch the orphan's property; give full measure; be just in speech even about relatives; fulfil Allah's covenant. This is My straight path; follow it and not other paths.",mz:"Tabataba'i notes that the commands are grouped under 'this is My straight path', so the path of al-Fatiha is given concrete content here: tawhid, parents, life, chastity, property, honesty, justice, covenant. He reads 'other paths' as any way that does not gather these together.",q:"Which of the ten do I treat as optional?",k:"Ten big rules: worship only Allah, be good to parents, be honest, be fair, keep promises."},
{s:7,f:19,t:31,n:"The tree, the whisper, and the clothing of taqwa",sum:"Adam and his wife in the garden; Satan whispers, swears he is a sincere adviser, and they taste the tree; their shame appears; they say: our Lord, we have wronged ourselves, forgive us. O children of Adam, We sent down clothing to cover you, and the clothing of taqwa is best. Take your adornment at every mosque, eat and drink but do not be excessive.",mz:"Al-Mizan reads the clothing of taqwa as the inner covering that the outer garment symbolises, and connects the whole passage to the verse on eating without excess: the first disorder was an appetite deceived by a false adviser. Tabataba'i treats 'do not be excessive' as the Quran's general principle of measure in all enjoyment.",q:"Who is the 'sincere adviser' whispering excess to me?",k:"Satan tricked Adam about food. Allah says: eat and drink, enjoy it, but do not go overboard."},
{s:7,f:172,t:174,n:"The covenant of 'am I not your Lord?'",sum:"When your Lord took from the children of Adam their descendants and made them witness over themselves: am I not your Lord? They said: yes, we witness. So that you cannot say on the Day of Judgement: we were unaware of this.",mz:"One of al-Mizan's deepest discussions. Tabataba'i argues that the verse describes a real witnessing in a dimension of existence prior to this world, the 'alam al-dharr', in which every soul knows its Lord by direct acquaintance, and that this is why no one can plead ignorance. He connects it to the fitrah verse (30:30): the covenant is the content of human nature.",q:"What in me already knows the answer before I argue?",k:"Before we were born, every soul already said yes to Allah. Deep inside, everyone knows Him."},
{s:9,f:71,t:72,n:"Believers as guardians of one another",sum:"The believing men and women are guardians of one another: they enjoin good and forbid wrong, establish prayer, give zakat, obey Allah and His Messenger; Allah will have mercy on them. Allah promises them gardens, and His good pleasure is greatest.",mz:"Tabataba'i contrasts this verse with the preceding description of the hypocrites, who are 'of one another' in corruption; believers are wali to each other in guarding. He notes that men and women are named equally, and that 'Allah's good pleasure' is set above the garden itself as the greater reward.",q:"Whose guardian am I, and who is mine?",k:"Believers look after each other, remind each other to do good, and pray together."},
{s:12,f:1,t:21,n:"Yusuf: the dream, the well, the house of the 'Aziz",sum:"We relate to you the best of stories. Yusuf's dream of eleven stars; Ya'qub's warning; the brothers' plot; the well; the caravan; sold for a few dirhams; the 'Aziz tells his wife to honour him; Allah establishes Yusuf in the land and teaches him interpretation.",mz:"Al-Mizan reads the surah as the story of pure servanthood (ikhlas) tested at every station: envy, slavery, temptation, prison, power. Tabataba'i explains 'the best of stories' by its completeness: one story, told once, showing how tawhid governs a whole life, and he treats Allah's repeated 'We' in the narrative as the real agent behind every turn.",q:"Where has a loss turned out to be the road?",k:"Yusuf's brothers were jealous and threw him in a well, but Allah was planning something good."},
{s:12,f:22,t:35,n:"Yusuf: the temptation and the prison",sum:"The wife of the 'Aziz tempts him; he says: I seek refuge in Allah; the shirt torn from behind; the women cut their hands; Yusuf says: prison is dearer to me than what they call me to; he is imprisoned though innocent.",mz:"Tabataba'i reads 'he would have inclined had he not seen the proof of his Lord' as describing a protection that comes from servanthood, not from the absence of desire. He discusses 'burhan' as a vision of the Lord's presence given to the purified, and reads the choice of prison as the clearest Quranic image of preferring Allah over ease.",q:"What is my 'prison is dearer to me' choice this month?",k:"Yusuf said no to something wrong even when it cost him his freedom. Being good can be hard."},
{s:12,f:36,t:57,n:"Yusuf: the dreams, the king, and the treasuries",sum:"Two prisoners' dreams; Yusuf calls them to tawhid before interpreting; years pass; the king's dream of seven fat and seven lean cows; Yusuf's plan of seven years of plenty and seven of famine; his innocence is established; set me over the treasuries of the land.",mz:"Al-Mizan notes that Yusuf refuses to leave prison until his name is cleared, placing honour of truth above freedom. Tabataba'i reads his request for office as service, not ambition: 'I am a knowing guardian' names the two qualities competence and trust, and the famine plan is presented as revelation turned into administration.",q:"Do I ask for responsibility, or wait to be handed it?",k:"Yusuf explained the king's dream and saved the whole country from hunger by planning ahead."},
{s:12,f:58,t:101,n:"Yusuf: the brothers, the shirt, and the reunion",sum:"The brothers come for grain; Binyamin is kept; Ya'qub's eyes whiten with grief but he says: I complain only to Allah; Yusuf reveals himself: no blame on you today; the shirt restores Ya'qub's sight; the family prostrates; Yusuf prays: take me as a Muslim and join me with the righteous.",mz:"Tabataba'i draws out Ya'qub's 'beautiful patience' as complaint directed only to Allah, and reads 'no blame on you today' as the fruit of a servanthood that has no grievance left to settle. He treats the closing prayer as the key to the surah: the dream fulfilled, Yusuf asks not for more kingdom but for a good ending.",q:"What forgiveness would complete a story in my family?",k:"Yusuf forgave his brothers completely and his father could see again. Forgiving fixes families."},
{s:14,f:7,t:7,n:"Gratitude and increase",sum:"And when your Lord proclaimed: if you are grateful, I will surely increase you; but if you are ungrateful, My punishment is severe.",mz:"Al-Mizan reads the increase as unspecified on purpose: it is increase in the blessing itself and beyond it, and gratitude is defined as using the blessing in the way its Giver intends. Tabataba'i connects it to Musa's reminder to his people, so gratitude is a community's path as well as a person's.",q:"What did I use today in a way its Giver would not have intended?",k:"When you really say thank you to Allah, He gives you more to be thankful for."},
{s:14,f:35,t:41,n:"Ibrahim's prayer for Makkah and his family",sum:"My Lord, make this city secure and keep me and my children from worshipping idols; I have settled some of my descendants in a barren valley near Your sacred House so they may establish prayer; make hearts incline to them; praise to Allah who gave me Isma'il and Ishaq in old age; make me and my descendants establishers of prayer; forgive me, my parents and the believers on the Day of Reckoning.",mz:"Tabataba'i reads the prayer as the charter of Makkah and of the Prophet's line, and notes its order: faith first, then prayer, then provision. The request 'make hearts incline to them' is read as the origin of the love that draws pilgrims. He also comments on 'my parents', taking it to refer to Ibrahim's actual parents and not to Azar, consistent with 9:114.",q:"What do I ask for my children first: faith, or comfort?",k:"Ibrahim prayed for his children to pray and for people to love them. Parents can pray like that too."},
{s:16,f:90,t:97,n:"Justice, excellence, and the good life",sum:"Allah commands justice, ihsan and giving to relatives, and forbids indecency, wrong and oppression; fulfil the covenant; do not break oaths; whatever is with you ends and what is with Allah endures; whoever does good, male or female, as a believer, We will give a good life.",mz:"Al-Mizan reads 16:90 as the most comprehensive verse of ethics, with 'adl as the foundation and ihsan as its completion, and explains why giving to relatives is singled out as the first circle of ihsan. On 16:97 Tabataba'i argues that the 'good life' is a real life granted in this world, a light and contentment the believer actually tastes, not only a promise for the next.",q:"Where is the good life already in my day, unnoticed?",k:"Be fair, do things beautifully, and be good to family; Allah gives good people a happy life."},
{s:17,f:23,t:30,n:"Parents, kin, and the measure of spending",sum:"Your Lord decreed that you worship none but Him and be good to parents; do not say 'uff'; lower to them the wing of humility and say: my Lord, have mercy on them as they raised me when I was small. Give the relative his due, and the needy and the traveller, and do not squander; do not tie your hand to your neck nor open it completely.",mz:"Tabataba'i notes the placement of parents immediately after tawhid as the Quran's ranking of duties, and reads 'as they raised me small' as the reason that keeps the duty alive after the parents' authority is gone. On spending, he reads the two images as the two extremes forbidden, with the middle course as the Quran's constant rule of measure.",q:"What is my 'uff', the small impatience I think does not count?",k:"Be gentle with Mama and Baba, do not even say 'uff', and pray for them as they looked after you."},
{s:17,f:36,t:39,n:"Knowledge before speech, humility before walking",sum:"Do not follow what you have no knowledge of; hearing, sight and heart will all be questioned. Do not walk on the earth proudly; you cannot tear the earth nor reach the mountains. That is from the wisdom your Lord revealed to you.",mz:"Al-Mizan reads 17:36 as a universal principle of knowledge and conduct: belief and action must rest on knowledge, and the three faculties are each held to account for what they followed. Tabataba'i treats the walking verse as the outward sign of the same inner order: the one who knows his smallness does not strut.",q:"What did I repeat today that I did not know to be true?",k:"Do not say things you are not sure about, and do not walk around like you are the biggest."},
{s:18,f:9,t:26,n:"The companions of the cave",sum:"Young men fled to a cave for their faith and prayed: our Lord, give us mercy and prepare for us right guidance. Allah sealed their ears for years; they awoke and sent one to the city with their old coin; the people learned of them; they stayed three hundred years and nine; say: Allah knows best how long.",mz:"Tabataba'i reads the story as a demonstration of resurrection in miniature and of Allah's guardianship over those who stand for tawhid in a hostile society. He discusses the sleepers' prayer, 'prepare for us right guidance' (rushd), as the model of what to ask in a time of trial, and treats the closing 'Allah knows best' as the Quran's correction of the people's quarrels over details.",q:"Where would I need to 'flee to a cave' to keep my faith whole?",k:"Young believers hid in a cave and slept for hundreds of years. Allah protected them the whole time."},
{s:18,f:32,t:44,n:"The man with two gardens",sum:"A parable of two men: one with two gardens of vines and date palms and a river between; he enters his garden wronging himself: I do not think this will ever perish. His companion: do you deny Him who created you from dust? Why did you not say: ma sha Allah, there is no power except through Allah? The garden is destroyed and he wrings his hands.",mz:"Al-Mizan reads the parable as the life of this world in picture: the garden is real, the pride is the error, and 'what Allah wills' is the sentence that would have kept the owner safe. Tabataba'i notes that the man's wrong was to see his wealth as his own and lasting, and that the companion's argument moves from creation to tawhid to the Hereafter.",q:"Over what do I need to say 'ma sha Allah, la quwwata illa billah' tonight?",k:"A man showed off his gardens and forgot Allah; the next day they were gone. Say ma sha Allah over your things."},
{s:18,f:60,t:82,n:"Musa and the servant given knowledge",sum:"Musa travels to the meeting of the two seas; the fish escapes; they find a servant of Allah given mercy and knowledge; Musa asks to follow him and promises patience; the boat is holed, the boy is killed, the wall is rebuilt; Musa objects three times; the servant explains each act, and says: I did not do it of my own accord.",mz:"Tabataba'i reads the three acts as examples of a knowledge of realities (ta'wil) hidden behind events, the same ta'wil discussed at 3:7, and treats al-Khidr's final words as the key: the acts were by Allah's command, so apparent wrong was concealed mercy. Musa's station as a law-bearing prophet is not lowered; the story shows that there are matters beyond the outward law that belong to another knowledge.",q:"Which event in my life am I still judging from the middle?",k:"Musa followed a wise teacher who did three strange things that all turned out to be kind."},
{s:19,f:16,t:36,n:"Maryam and the birth of Isa",sum:"Maryam withdraws; the spirit appears as a man; she seeks refuge; he says: I am a messenger of your Lord to give you a pure boy. She retires to a distant place; the pains bring her to the palm trunk; a voice says: do not grieve, shake the trunk and fresh dates will fall; eat, drink, be comforted. The infant speaks: I am the servant of Allah.",mz:"Al-Mizan draws attention to the honour given to Maryam as a sign for the worlds, and reads 'shake the trunk' as the pairing of divine help with human effort. Tabataba'i treats Isa's first words, 'I am the servant of Allah', as the surah's refutation of divinity claims, placed in the mouth of the child himself.",q:"What trunk is Allah asking me to shake before the dates fall?",k:"Baby Isa was born under a date tree. Allah told Maryam to shake it and eat the sweet dates."},
{s:20,f:9,t:36,n:"Musa at the fire and the prayer for ease",sum:"Musa sees a fire, hears: I am your Lord, remove your sandals, you are in the sacred valley; establish prayer for My remembrance; what is in your hand? My staff; throw it; the serpent; his hand white; go to Pharaoh. Musa prays: expand my chest, ease my task, untie the knot in my tongue, and give me a helper from my family, Harun.",mz:"Tabataba'i reads 'I am Allah, there is no god but Me, so worship Me and establish prayer for My remembrance' as the first revelation to Musa and the summary of all revelation: tawhid, worship, and prayer as remembrance. He treats the prayer for ease as the prophet's recognition that the task exceeds the self, and notes that Allah grants every request at once.",q:"What is the 'knot in my tongue' I should ask to have untied?",k:"Musa was scared to speak to the king, so he asked Allah to make his heart brave. Allah said yes."},
{s:21,f:51,t:73,n:"Ibrahim breaks the idols",sum:"We gave Ibrahim his guidance before; he asks his people what the statues are; he vows to plot against the idols; he breaks them except the largest; they ask who did it; he says: the big one did, ask them if they can speak; they return to themselves, then revert; they say burn him; We said: O fire, be cool and safe for Ibrahim.",mz:"Al-Mizan reads Ibrahim's 'the big one did it' as an argument staged to make the people confess the idols' helplessness, not a lie. Tabataba'i treats 'they returned to themselves' as the moment reason spoke, and 'then they were turned on their heads' as the reversion to habit over proof, a pattern he finds across the Quran.",q:"When reason speaks to me, how quickly do I turn back on my head?",k:"Ibrahim showed everyone that statues cannot even talk. When they threw him in a fire, Allah made it cool."},
{s:21,f:83,t:90,n:"Ayyub, Yunus, Zakariyya: three prayers",sum:"Ayyub: harm has touched me and You are the most merciful; We removed his harm. Dhun-Nun went in anger, called in the darkness: there is no god but You, glory to You, I was among the wrongdoers; We saved him, and thus do We save the believers. Zakariyya: do not leave me alone; We gave him Yahya.",mz:"Tabataba'i reads the three prayers as three forms of servanthood: Ayyub names only Allah's mercy, not his own need; Yunus confesses with tawhid and no request; Zakariyya asks while affirming Allah as the best inheritor. He draws attention to 'thus do We save the believers' as a promise attached to the dua of Yunus for all who use it.",q:"Which of the three prayers is mine tonight?",k:"Three prophets prayed in three ways and Allah answered each. Yunus's dua works for everyone."},
{s:24,f:35,t:38,n:"The verse of Light",sum:"Allah is the Light of the heavens and the earth; His light is like a niche in which is a lamp, the lamp in a glass, the glass like a shining star, lit from a blessed olive tree neither of east nor west, whose oil would almost glow without fire; light upon light; Allah guides to His light whom He wills. In houses Allah permitted to be raised, men glorify Him whom no trade distracts.",mz:"One of al-Mizan's longest discussions. Tabataba'i reads 'light' as that by which things appear, so Allah is light in the sense that all existence is manifest by Him; the parable describes the light of faith in the believer's heart, with the niche, glass, lamp and oil as its receptacles and source. He connects 'the houses' to the homes of the prophets and their Households by narration, while reading the verse's universal meaning first.",q:"What trade distracts me from remembering, and what would turn the lamp up?",k:"Allah's guidance is like a beautiful lamp that lights up a dark room. Faith makes your heart bright."},
{s:25,f:63,t:77,n:"The servants of the Merciful",sum:"The servants of the Merciful walk humbly and answer the ignorant with peace; they spend the night prostrating and standing; they ask protection from Hell; they are neither wasteful nor stingy; they do not call on another god, kill, or fornicate; they do not witness falsehood; when reminded they do not fall deaf and blind; they pray: make our spouses and children the comfort of our eyes, and make us leaders of the God-conscious.",mz:"Tabataba'i reads the passage as a complete portrait of servanthood, beginning with how one walks and ending with how one prays for one's family. He notes that moderation in spending is placed among the signs, between night prayer and tawhid, and reads 'make us imams for the muttaqin' as a request to lead in good, which the Quran permits to ask for.",q:"Which of these twelve marks could my family see in me this week?",k:"Good people walk gently, say 'peace' to rude people, pray at night, share wisely, and pray for their family."},
{s:27,f:15,t:19,n:"Sulayman and the ant",sum:"We gave Dawud and Sulayman knowledge; Sulayman inherited Dawud and said: we were taught the speech of birds. His hosts of jinn, men and birds marched; at the valley of the ants an ant said: enter your dwellings lest Sulayman and his hosts crush you unawares. He smiled at her words and said: My Lord, enable me to be grateful for Your favour on me and on my parents, and to do good that pleases You, and admit me by Your mercy among Your righteous servants.",mz:"Al-Mizan reads Sulayman's prayer as the model response to power: gratitude first, then good work, then the plea to be counted among the righteous by mercy rather than merit. Tabataba'i treats the ant's speech as real, part of the kingdom given to him, and the smile as the mark of a king whom greatness did not harden.",q:"What power do I hold that should make me smile at an ant?",k:"A tiny ant warned her friends about the army. King Sulayman smiled and thanked Allah for everything."},
{s:28,f:76,t:84,n:"Qarun",sum:"Qarun was of Musa's people and oppressed them; his treasures' keys burdened a band of strong men; his people said: do not exult; seek the Hereafter with what Allah gave you and do not forget your share of this world; he said: I was given it for my knowledge. He went out in his splendour; the people wished for his like; the knowing said: Allah's reward is better. We caused the earth to swallow him and his house.",mz:"Tabataba'i reads 'do not forget your share of this world' as permission and limit at once: this world is to be used for the next, and the share is what serves that. Qarun's error is named in his own words, attributing wealth to his knowledge, and al-Mizan contrasts the two crowds, those who wished for his wealth and those who knew, as the two ways of looking at a rich man.",q:"What do I say 'I earned by my knowledge' that was given?",k:"Qarun was so rich his keys were heavy, and he said 'I did it myself'. Then it was gone. Say Alhamdulillah instead."},
{s:30,f:20,t:30,n:"Signs in creation and the religion of fitrah",sum:"Among His signs: He created you from dust; He created spouses for you that you may find rest in them, and placed love and mercy between you; the heavens and earth, your languages and colours, your sleep and your seeking of His bounty. So set your face to the religion, upright, the fitrah of Allah upon which He created people; there is no changing Allah's creation.",mz:"The fitrah verse is central to Tabataba'i's thought: religion is not imposed on human nature but is its own demand, the way a seed demands its tree. Al-Mizan reads 'no changing Allah's creation' as the reason the true religion is one across the prophets. On 30:21, he treats the love and mercy between spouses as a created sign placed in human nature for the family's sake.",q:"What does my nature demand that my habits deny?",k:"Allah made everyone with a clean heart that already loves Him. Being good is being yourself."},
{s:31,f:12,t:19,n:"Luqman's counsel",sum:"We gave Luqman wisdom: be grateful to Allah. He said to his son: do not associate anything with Allah; We enjoined on man goodness to parents, be grateful to Me and to your parents; but if they strive to make you associate, do not obey them, yet keep company with them kindly; my son, nothing is hidden from Allah; establish prayer, enjoin good, forbid wrong, be patient; do not turn your cheek in pride, do not walk arrogantly; be moderate in your walk and lower your voice.",mz:"Al-Mizan notes that the first act of the wise man is gratitude, which Tabataba'i reads as the definition of wisdom itself: seeing a blessing as a blessing. He draws out the order of the counsel, tawhid, parents, awareness of Allah, prayer, social duty, patience, humility, and treats 'the harshest of voices is the braying of donkeys' as the Quran's teaching that loudness is a defect of character.",q:"Which line of Luqman's counsel would my children say I need?",k:"A wise father told his son: thank Allah, be kind to parents, pray, do good, be patient, and talk softly."},
{s:33,f:33,t:33,n:"The verse of purification",sum:"Stay in your houses, do not display yourselves as in the former ignorance, establish prayer, give zakat, obey Allah and His Messenger. Allah only wishes to remove impurity from you, O People of the House, and to purify you completely.",mz:"Al-Mizan's discussion is among its most extensive. Tabataba'i argues from the grammar, the masculine plural address, the restrictive 'only', and the narrations of the cloak reported in Sunni and Shi'a collections, that 'the People of the House' here are the Prophet, 'Ali, Fatima, al-Hasan and al-Husayn, and that the 'wish' is a creative (takwini) will that purifies them in fact. He answers the reading that it addresses the wives from the context, noting the change of pronoun.",q:"What impurity would I ask to have removed if I believed it possible today?",k:"Allah promised to keep the Prophet's family pure and clean of all wrong. The Prophet covered them with his cloak."},
{s:36,f:13,t:32,n:"The man who came running",sum:"The parable of the town: two messengers, then a third; the people deny and threaten; a man comes running from the farthest part of the city: follow the messengers, follow those who ask no reward and are guided; why should I not worship Him who created me? He is told: enter the garden; he says: would that my people knew how my Lord forgave me.",mz:"Tabataba'i reads the running man as the believer's model in a hostile city: he argues from creation and from the messengers' selflessness, and even after death wishes good for his people. Al-Mizan notes that his entry into the garden is told as immediate, which Tabataba'i uses as evidence for life in the barzakh between death and resurrection.",q:"From which 'farthest part of the city' should I run today?",k:"A brave man ran across the town to tell people to listen to Allah's messengers. Even in Paradise he wished them well."},
{s:39,f:53,t:55,n:"Do not despair of the mercy of Allah",sum:"Say: O My servants who have transgressed against themselves, do not despair of Allah's mercy; Allah forgives all sins; He is the Forgiving, the Merciful. Turn to your Lord and submit to Him before the punishment comes; follow the best of what was sent down to you.",mz:"Al-Mizan reads 'My servants' as the address that makes the promise possible: the relationship of servanthood is not broken by sin. Tabataba'i discusses 'forgives all sins' with the following verse: forgiveness is universal in scope but reached through turning and submission, so the verse is an invitation, not a licence.",q:"What have I decided is beyond forgiveness, and on whose authority?",k:"Allah says: My servants, never think I will not forgive you. Just come back to Me."},
{s:42,f:36,t:43,n:"Consultation, anger, and forgiveness",sum:"What is with Allah is better and more lasting for those who believe and rely on their Lord, who avoid great sins, who forgive when angry, who answer their Lord and establish prayer, whose affair is consultation among them, who spend, and who defend themselves when wronged. The recompense of a wrong is its like, but whoever pardons and reconciles, his reward is with Allah. Whoever is patient and forgives, that is of the resolve of affairs.",mz:"Tabataba'i reads 'their affair is consultation among them' as the Quran's description of a believing community's way of deciding, and sets it beside the permission to resist wrong and the praise of pardon: justice is the limit, forgiveness the higher road. He notes the pairing of 'forgive when angry' with 'answer their Lord', so self-control is treated as a response to Allah.",q:"Where did I take 'its like' when pardon was open to me?",k:"Good people talk together before deciding, forgive when angry, and share what they have."},
{s:49,f:10,t:13,n:"Brotherhood, mockery, suspicion, and the one family",sum:"The believers are brothers, so make peace between your brothers. Let no people mock another; do not defame one another; avoid much suspicion, for some suspicion is sin; do not spy or backbite. O mankind, We created you from a male and a female and made you peoples and tribes that you may know one another; the most noble of you is the most God-conscious.",mz:"Al-Mizan reads the sequence from brotherhood among believers to kinship among all humanity, and treats 49:13 as the Quran's denial of every ground of superiority except taqwa, which only Allah measures. Tabataba'i explains 'that you may know one another' as the purpose of difference: acquaintance, not ranking.",q:"Whom did I rank today, and by what measure?",k:"Allah made different peoples so we can get to know each other. Nobody is better except by being more careful with Allah."},
{s:55,f:1,t:13,n:"Ar-Rahman: the Quran, the balance, the fruit",sum:"The Merciful taught the Quran, created man, taught him speech; the sun and moon in reckoning; the star and the tree prostrate; He raised the sky and set the balance, that you not transgress in the balance; the earth He laid for creatures, with fruit, palms, grain and fragrant plants. Which of your Lord's favours will you deny?",mz:"Tabataba'i notes that the first favour listed is the Quran, before the creation of man, and that speech (bayan) follows at once: understanding and expression are placed among the greatest mercies. He reads 'the balance' in both its cosmic and its moral sense, so the command 'do not transgress in the balance' covers measure in trade and measure in living.",q:"Where am I transgressing in the balance: in food, words, or time?",k:"Allah taught us to speak and read, and gave us fruit and grain. Which gift could we say is not a gift?"},
{s:56,f:57,t:74,n:"The seed, the water, the fire: who made them?",sum:"We created you; why do you not affirm it? Have you seen what you emit? Do you create it or do We? Have you seen what you sow? Do you make it grow or do We? Have you seen the water you drink? Did you send it down from the clouds? Have you seen the fire you kindle? Did you produce its tree? So glorify the name of your mighty Lord.",mz:"Al-Mizan reads the four questions as a demonstration of resurrection through creation: the One who brings seed, grain, water and fire from nothing can bring the dead to life. Tabataba'i notes that each example is taken from daily sustenance, so the argument is meant to be felt at every meal.",q:"At tonight's meal, which of the four did I thank Him for?",k:"Who makes the seeds grow and the rain fall? We cannot. Only Allah. So we say thank you at dinner."},
{s:59,f:18,t:24,n:"Look at what you sent ahead; the beautiful names",sum:"Fear Allah, and let every soul look at what it has sent ahead for tomorrow. Do not be like those who forgot Allah, so He made them forget themselves. Had We sent down this Quran on a mountain, you would have seen it humbled and split apart from fear of Allah. He is Allah, the Knower of the unseen, the Merciful, the King, the Holy, the Peace, the Faithful, the Guardian, the Mighty, the Compeller, the Creator, the Shaper; to Him belong the most beautiful names.",mz:"Tabataba'i reads 'forgot Allah so He made them forget themselves' as the Quran's deepest statement on self-knowledge: the self is known in relation to its Lord, and forgetting Him empties the self of meaning. The list of names is read as a summary of the whole surah's theme, and the parable of the mountain as the weight the Quran should have on a heart.",q:"What did I send ahead today?",k:"Before you sleep, look at what good you sent ahead for tomorrow. And learn Allah's beautiful names."},
{s:62,f:9,t:11,n:"Friday: the call, the prayer, the work",sum:"When the call is made for prayer on Friday, hasten to the remembrance of Allah and leave trade. When the prayer is finished, disperse through the land and seek Allah's bounty, and remember Allah much, that you may succeed. But when they saw trade or amusement they rushed to it and left you standing.",mz:"Al-Mizan reads the two commands as balanced: leave trade for the prayer, then return to work as seeking Allah's bounty, with remembrance carried into both. Tabataba'i notes the rebuke in the last verse as showing that the community was still learning the weight of remembrance against gain.",q:"Do I carry remembrance from the prayer into the office, or leave it at the door?",k:"On Friday we stop work to pray, and then go back to work remembering Allah."},
{s:67,f:1,t:4,n:"Al-Mulk: the perfect sky and the best deed",sum:"Blessed is He in whose hand is the kingdom; who created death and life to test which of you is best in deed; who created seven heavens in layers; you see no flaw in the creation of the Merciful; return your gaze, do you see any crack? Return your gaze again, it will come back to you humbled and weary.",mz:"Tabataba'i notes that death is named before life, which he reads as a sign that death is a creation and a passage, not a mere ending. 'Best in deed' is explained as the deed most sincere and most correct together, and the flawless creation is read as evidence that the test has a wise purpose.",q:"Which one deed today could I make best rather than most?",k:"Look at the sky. Can you find a crack? Allah made it perfect. Read this surah before bed."},
{s:73,f:1,t:10,n:"Al-Muzzammil: the night and the heavy word",sum:"O you wrapped in garments, stand the night except a little, half of it or less or more, and recite the Quran with measured recitation. We will cast upon you a heavy word. The rising of the night is firmer in impression and more upright in speech. By day you have long occupation. Remember the name of your Lord and devote yourself to Him entirely.",mz:"Al-Mizan reads the night vigil as the preparation for receiving the 'heavy word', so worship precedes mission. Tabataba'i treats 'measured recitation' (tartil) as reading that lets meaning land, and reads 'devote yourself entirely' (tabattul) as cutting the heart's attachment to all but Him.",q:"Could I give the Quran ten slow minutes before the day's long occupation?",k:"The Prophet prayed at night to get strong for the day. Reading the Quran slowly helps it stay in your heart."},
{s:76,f:5,t:12,n:"Al-Insan: they feed the needy, the orphan and the captive",sum:"The righteous drink from a cup mixed with camphor; they fulfil vows and fear a widespread day; they give food, despite loving it, to the needy, the orphan and the captive: we feed you only for Allah's face, we want no reward or thanks from you; so Allah protected them from that day and gave them radiance and joy.",mz:"Tabataba'i presents the narration, in Sunni and Shi'a sources, that the verses were revealed about 'Ali, Fatima, al-Hasan and al-Husayn giving their iftar away for three nights, and reads 'for Allah's face' as the definition of ikhlas: no reward, no thanks, not even gratitude expected. Al-Mizan notes 'despite loving it', so the merit is in giving what one wants.",q:"What did I give today that I actually wanted to keep?",k:"The Prophet's family gave their dinner to hungry people three nights in a row and said: we only do this for Allah."},
{s:87,f:1,t:19,n:"Al-A'la: He who created and proportioned",sum:"Glorify the name of your Lord, the Most High, who created and proportioned, who measured and guided, who brought out the pasture. We will make you recite and you will not forget. Remind, if reminding benefits. He who purifies himself and remembers his Lord's name and prays has succeeded. But you prefer this life, though the Hereafter is better and more lasting. This is in the earlier scriptures, of Ibrahim and Musa.",mz:"Al-Mizan reads 'measured and guided' as a statement of universal guidance: every creature is given a measure and guided to its perfection, which Tabataba'i develops as a foundation of his view of creation. He notes the surah's closing claim that its teaching is in the scriptures of Ibrahim and Musa, the unity of revelation.",q:"What has Allah measured for me that I keep trying to re-measure?",k:"Allah made everything just the right size and showed it what to do. He will help you remember what you learn."},
{s:89,f:15,t:30,n:"Al-Fajr: the test of plenty and the serene soul",sum:"When his Lord tests man with honour and favour he says: my Lord has honoured me; when He restricts his provision he says: my Lord has humiliated me. No. You do not honour the orphan, nor urge feeding the poor; you devour inheritance and love wealth greatly. When the earth is pounded and your Lord comes with the angels, man will remember, but how will remembrance help him? O serene soul, return to your Lord, pleased and pleasing; enter among My servants, enter My garden.",mz:"Tabataba'i reads the surah's correction, 'No', as the denial that wealth or poverty measure Allah's regard; both are tests, and the test is passed in how the orphan and the poor are treated. Al-Mizan reads 'the serene soul' as the soul at rest in its Lord through certainty, and 'enter among My servants' as the highest station, servanthood, before the garden is named.",q:"Do I read my income as a verdict, or as a test?",k:"Being rich or poor is a test, not a prize. The calm, peaceful soul is invited home to Allah."},
{s:91,f:1,t:10,n:"Ash-Shams: eleven oaths and the soul",sum:"By the sun and its brightness, the moon when it follows, the day when it reveals, the night when it covers, the sky and He who built it, the earth and He who spread it, the soul and He who proportioned it and inspired it with its wickedness and its righteousness: he has succeeded who purifies it, and he has failed who buries it.",mz:"Al-Mizan reads 'inspired it with its wickedness and its righteousness' as the knowledge of good and evil placed in every soul, the practical side of fitrah. Tabataba'i treats the eleven oaths as the Quran's longest run of oaths, all converging on one sentence: success is the purification of the soul, and failure is its burial under what it was not made for.",q:"What am I burying my soul under this week?",k:"Allah swears by the sun and the moon that the person who keeps their heart clean wins."},
{s:93,f:1,t:11,n:"Ad-Duha: your Lord has not forsaken you",sum:"By the morning brightness and the night when still, your Lord has not forsaken you nor does He hate you; the last will be better than the first; your Lord will give you and you will be satisfied. Did He not find you an orphan and shelter you, lost and guide you, poor and enrich you? So do not oppress the orphan, nor repulse the asker, and speak of your Lord's blessing.",mz:"Tabataba'i reads the surah as comfort to the Prophet during the pause in revelation, and the three past favours as the proof of future care. Al-Mizan draws the three commands from the three favours: sheltered, so shelter the orphan; guided, so do not repulse the one who asks; enriched, so speak of the blessing. Gratitude is turned into conduct.",q:"Which past care of Allah do I need to remember before I worry about tomorrow?",k:"Allah told the Prophet: I looked after you when you were a little orphan, and I have not forgotten you."},
{s:94,f:1,t:8,n:"Al-Inshirah: with hardship, ease",sum:"Did We not expand your chest, remove your burden that weighed on your back, and raise your renown? With hardship comes ease; truly with hardship comes ease. So when you are free, labour on, and to your Lord turn with longing.",mz:"Al-Mizan reads the two 'ease' clauses as two different eases for one hardship, the definite 'the hardship' against the indefinite 'ease', which is the basis of the saying that one hardship will not overcome two eases. Tabataba'i treats 'when you are free, labour on' as the rhythm of a prophet's life: no rest except in turning toward Him.",q:"What is the ease that is already with my hardship?",k:"Allah made the Prophet's heart light. Every hard thing comes with an easy thing, twice."},
{s:96,f:1,t:8,n:"Al-'Alaq: read, in the name of your Lord",sum:"Read, in the name of your Lord who created; created man from a clinging clot. Read, and your Lord is the most Generous, who taught by the pen, taught man what he did not know. No, man transgresses because he sees himself self-sufficient. To your Lord is the return.",mz:"Tabataba'i reads the first revelation as joining creation and teaching: the same Lord who created from a clot taught by the pen. Al-Mizan draws out 'he sees himself self-sufficient' as the root of every transgression, placed immediately after the praise of knowledge, so that knowledge without servanthood becomes the very thing that corrupts.",q:"Where do I see myself as self-sufficient, and what does it make me do?",k:"The first word Allah sent was 'Read'. Reading and learning are gifts from the most Generous."},
{s:97,f:1,t:5,n:"Al-Qadr: the night of decree",sum:"We sent it down in the Night of Decree; and what will make you know the Night of Decree? The Night of Decree is better than a thousand months; the angels and the Spirit descend in it by their Lord's leave for every affair; peace it is until the rising of dawn.",mz:"Al-Mizan reads the night as recurring every year, since the angels descend 'for every affair' in the present tense, and discusses the sending down of the whole Quran at once in this night alongside its gradual revelation over twenty-three years. Tabataba'i treats 'the Spirit' as a creature greater than the angels, and 'peace until dawn' as the character of the night itself.",q:"If one night were worth a thousand months, how would I spend it?",k:"One night in Ramadan is better than a thousand months. The angels come down and it is all peace."},
{s:103,f:1,t:3,n:"Al-'Asr: the four conditions",sum:"By time, mankind is in loss, except those who believe, do righteous deeds, counsel one another to truth, and counsel one another to patience.",mz:"Tabataba'i reads the oath by time as the whole span of human history, in which loss is the rule and the exception has four parts: faith, deeds, and two mutual counsels. Al-Mizan notes that the last two make salvation communal: one is saved with others, by reminding and being reminded of truth and patience.",q:"Whom did I counsel to truth this week, and who counselled me?",k:"Time runs out for everyone. Four things save you: believe, do good, help others be truthful, help others be patient."},
{s:107,f:1,t:7,n:"Al-Ma'un: small kindnesses",sum:"Have you seen the one who denies the religion? It is he who pushes away the orphan and does not urge feeding the poor. So woe to those who pray, who are heedless of their prayer, who make a show, and withhold small kindnesses.",mz:"Al-Mizan reads the surah as the Quran's definition of denying the religion by conduct: cruelty to the orphan and indifference to the hungry. Tabataba'i treats 'heedless of their prayer' as prayer emptied of its meaning, shown by its failure to produce the small kindnesses, al-ma'un, that a neighbour needs.",q:"What small kindness did I withhold because it was small?",k:"Real faith shows in small kindnesses: sharing a pot, lending a pen, being gentle with an orphan."},
{s:112,f:1,t:4,n:"Al-Ikhlas: say, He is Allah, One",sum:"Say: He is Allah, One; Allah, the Eternal Refuge; He neither begets nor is begotten; and there is none comparable to Him.",mz:"Tabataba'i explains 'ahad' as a oneness that admits no division and no second, distinct from 'wahid', and reads 'samad' as the One to whom all needs are directed while He needs none. Al-Mizan treats the surah as the whole of tawhid, which is why the narrations weigh it as a third of the Quran.",q:"What do I treat as 'samad', the thing I turn to first in need?",k:"Allah is One. He does not need anyone. Nobody is like Him. Four lines that say everything."},
/* ---- Second set of close readings (November 2026). Drafts until reviewed; see reviews.ts. ---- */
{s:2,f:21,t:22,n:"Al-Baqarah 21–22, the first command: worship",sum:"The first command addressed to all people in the Quran: worship your Lord who created you and those before you, so that you may become God-conscious; He made the earth a bed and the sky a canopy and sent rain for your provision, so do not set up rivals to Him while you know.",mz:"Al-Mizan notes that this is the first imperative in the mushaf and that it is addressed to people as such, not to believers, because creation and provision are reasons everyone already has. He reads 'so that you may be God-conscious' as the fruit of worship rather than its condition, and 'while you know' as the Quran's refusal to excuse idolatry by ignorance.",q:"What do I know about who feeds me, and whom do I thank first?",k:"The first thing Allah asks everyone to do is to worship Him, because He made us and gives us rain and food."},
{s:2,f:45,t:46,n:"Al-Baqarah 45–46, help in patience and prayer",sum:"Seek help through patience and prayer; it is hard except for the humble, those who are sure they will meet their Lord and return to Him.",mz:"Al-Mizan takes 'patience' here to include the fast, following the narrations, and explains why prayer is heavy except for the humble: khushu' is the state of someone who knows they stand before One who sees them. He links the verse to 2:153, the same instruction repeated for the believers, and reads 'they think' as certainty in the Quran's usage.",q:"When I am stuck, is prayer the first thing I reach for or the last?",k:"When something is hard, Allah says: be patient and pray. It is easy for people who remember they are standing in front of Allah."},
{s:2,f:177,t:177,n:"Al-Baqarah 177, the verse of righteousness",sum:"Righteousness is not turning faces east or west, but faith in Allah, the Last Day, the angels, the Book and the prophets; giving wealth despite loving it to relatives, orphans, the needy, the traveller, the beggar and for freeing captives; prayer, zakat, keeping promises, and patience in hardship and in battle. Those are the truthful and the God-conscious.",mz:"Al-Mizan reads the verse as a complete definition of the religion, in order: belief, giving, worship, honesty, patience. He notes that 'giving wealth despite loving it' is the Quran's standard for charity, that the recipients are listed by nearness, and that the verse ends by naming the people, 'the truthful', so that birr is a description of persons and not of acts.",q:"Which of the five parts of this verse is missing from my week?",k:"Being good is not about which way you face. It is believing, giving even when you love your money, praying, keeping promises and being patient."},
{s:2,f:261,t:265,n:"Al-Baqarah 261–265, the seed and the garden on a hill",sum:"Spending in Allah's way is like a grain that grows seven ears with a hundred grains each; Allah multiplies for whom He wills. Charity followed by reminder and hurt is lost, like rain on a rock with dust on it; charity seeking Allah's pleasure is like a garden on high ground that gives double after rain, and dew if no rain.",mz:"Al-Mizan reads the three parables as one lesson on intention: the multiplication belongs to spending 'in Allah's way', the hurt and reminder strip the deed of its growth, and the garden on the hill shows that a sincere deed is productive in every weather. He emphasises 'a kind word and forgiveness are better than charity followed by hurt'.",q:"Have I ever reminded someone of what I gave them?",k:"Giving is like planting a seed that grows seven hundred seeds. But if you give and then show off or hurt the person, the seed dies."},
{s:3,f:14,t:17,n:"Aal Imran 14–17, what people love and what is better",sum:"Beautified for people is the love of desires: women, children, heaps of gold and silver, branded horses, cattle and land. That is the enjoyment of this life; with Allah is the best return. Shall I tell you of better: gardens with their Lord, purified spouses and Allah's pleasure, for those who are patient, truthful, obedient, generous and who seek forgiveness before dawn.",mz:"Al-Mizan reads 'beautified for people' as a description, not a condemnation: the desires are natural, and the fault is in stopping at them. He lists the five qualities of the believers in verse 17 as the ladder out, and singles out seeking forgiveness in the last part of the night as the practice the Quran keeps returning to.",q:"Which of the six loved things would I find hardest to hold loosely?",k:"People love nice things, and that is normal. Allah says there is something even better waiting for those who are patient, honest and say sorry before dawn."},
{s:3,f:26,t:27,n:"Aal Imran 26–27, Owner of all kingdoms",sum:"O Allah, Owner of sovereignty: You give kingship to whom You will and take it from whom You will; You honour and You humble; in Your hand is all good; You are able over everything. You merge night into day and day into night, bring the living from the dead and the dead from the living, and provide without measure.",mz:"Al-Mizan reads the prayer as the believer's answer to the power of states that seem to decide everything: sovereignty is lent, honour is given, and the same hand that turns night into day turns one ruler into another. He notes that 'in Your hand is the good' does not add 'and the evil', because evil is the absence of a good that was withheld.",q:"Whose power am I afraid of this week, and who gave it?",k:"Kings and bosses only have power because Allah lent it to them. Allah can take it back, and He gives without counting."},
{s:3,f:31,t:32,n:"Aal Imran 31–32, if you love Allah, follow me",sum:"Say: if you love Allah, follow me and Allah will love you and forgive your sins. Say: obey Allah and the Messenger; if they turn away, Allah does not love the disbelievers.",mz:"Al-Mizan makes this verse the test of a claim: love of Allah is real only when it becomes following of the Prophet, since the Prophet is the lived form of what Allah wants, and the reward of that following is Allah's own love. He stresses that the verse turns the direction of love around: the servant starts by loving, and ends by being loved.",q:"Which habit of the Prophet have I copied this month?",k:"If you really love Allah, copy the Prophet. Then Allah will love you back."},
{s:3,f:169,t:171,n:"Aal Imran 169–171, the living martyrs",sum:"Do not think of those killed in Allah's way as dead; they are alive with their Lord, provided for, rejoicing in what Allah gave them and glad for those left behind who will join them, that they have nothing to fear or grieve.",mz:"Al-Mizan takes the verse as plain proof of life in the barzakh, the interval between death and resurrection, and reads 'provided for' and 'rejoicing' as a real condition and not a figure of speech. He notes that the martyrs' gladness is for those still on the road, which makes the verse a consolation to the living as much as a promise to the dead.",q:"Who in my family is 'alive with their Lord', and how do I remember them?",k:"People who die for Allah are not really gone. They are alive with Him, happy, and waiting for the people they love."},
{s:3,f:190,t:195,n:"Aal Imran 190–195, those who remember standing, sitting and lying",sum:"In the creation of the heavens and the earth and the alternation of night and day are signs for people of understanding, who remember Allah standing, sitting and on their sides, and reflect on creation: Our Lord, You did not create this in vain; glory to You; save us from the Fire. Their prayer for forgiveness and firmness is answered: I never waste the work of any worker among you, male or female.",mz:"Al-Mizan calls this the Quran's portrait of the ulu al-albab: remembrance in every bodily state joined to thought about creation, so that worship and reason are one act. He reads 'You did not create this in vain' as the conclusion that thought reaches, and notes that the answer 'male or female, you are of one another' makes the reward independent of sex.",q:"When did I last look at the sky long enough to say 'You did not make this for nothing'?",k:"Smart people remember Allah everywhere, standing, sitting and lying down, and they look at the sky and say: Allah, You made all this for a reason."},
{s:4,f:82,t:82,n:"An-Nisa 82, a Book without contradiction",sum:"Do they not reflect on the Quran? Had it been from other than Allah they would have found in it much contradiction.",mz:"Al-Mizan reads the verse as the Quran's own proof of itself: a text revealed over twenty-three years, in peace and war, on every subject, with no contradiction between its parts, could not come from a human mind whose views change. He makes the verse the basis of his method, explaining the Quran by the Quran, since a consistent text interprets itself.",q:"Which two verses seem to me to disagree, and have I read them together?",k:"The Quran came over 23 years and nothing in it disagrees with anything else. That is one way we know it is from Allah."},
{s:5,f:8,t:8,n:"Al-Ma'idah 8, justice even toward those you dislike",sum:"Be steadfast for Allah as witnesses in justice, and do not let hatred of a people make you unjust. Be just: that is nearer to God-consciousness.",mz:"Al-Mizan reads the verse with 4:135, where justice is demanded even against oneself and one's parents; here it is demanded even toward an enemy. He notes that justice is named 'nearer to taqwa', so that fairness to someone you dislike is a religious act and not only a social one.",q:"Who do I dislike enough that I might not be fair to them?",k:"Even if you do not like someone, you must still be fair to them. Being fair is close to being good with Allah."},
{s:5,f:32,t:32,n:"Al-Ma'idah 32, one soul and all of humanity",sum:"Because of that We decreed for Bani Israel that whoever kills a soul, other than for a soul or for corruption in the land, it is as if he had killed all of humanity; and whoever saves one, it is as if he had saved all of humanity.",mz:"Al-Mizan explains the 'as if': humanity is a single reality present whole in each person, so that the one who treats a single life as nothing has denied the worth of the human as such. He notes that the verse follows the story of Adam's two sons, and that the two exceptions are the law's own limits, not loopholes.",q:"Whose life do I weigh less than my own, and why?",k:"One person is so important that hurting one is like hurting everybody, and saving one is like saving everybody."},
{s:6,f:59,t:62,n:"Al-An'am 59–62, the keys of the unseen",sum:"With Him are the keys of the unseen; none knows them but He. He knows what is on land and sea; not a leaf falls but He knows it, nor a grain in the darkness of the earth, nor anything wet or dry, but it is in a clear book. He takes your souls by night and knows what you earn by day; He is the Master over His servants and sends guardians, until death comes and His messengers take the soul.",mz:"Al-Mizan reads 'the keys of the unseen' as the sources from which events issue, known to Allah alone, and takes 'a clear book' as the record in which everything exists before it appears. He explains sleep as a lesser taking of the soul that proves the greater, and notes that the angels who 'never fail' are the Quran's answer to the fear of death as an accident.",q:"Which falling leaf in my life did Allah not know about?",k:"Allah knows every leaf that falls and every seed in the dark ground. He watches over you when you sleep and when you wake."},
{s:7,f:199,t:201,n:"Al-A'raf 199–201, take to pardon",sum:"Take to pardon, command what is right and turn away from the ignorant. If a prompting from Satan stirs you, seek refuge in Allah. Those who are God-conscious, when a touch from Satan reaches them, remember, and then they see.",mz:"Al-Mizan calls 199 the whole of good character in three clauses and reads 'turn away from the ignorant' as refusing to answer provocation on its own level. He takes 'remember, and then they see' as the mechanism of taqwa: the touch of Satan clouds sight, remembrance clears it, and the believer differs from others not in never being touched but in how fast he remembers.",q:"What is the last provocation I answered on its own level?",k:"Forgive easily, tell people what is good, and walk away from silly arguments. If a bad thought comes, say 'a'udhu billah' and it goes."},
{s:8,f:2,t:4,n:"Al-Anfal 2–4, hearts that tremble",sum:"The believers are those whose hearts tremble when Allah is mentioned, whose faith grows when His verses are recited, who rely on their Lord, keep prayer and spend from what He gave them. Those are the believers in truth; they have ranks with their Lord, forgiveness and generous provision.",mz:"Al-Mizan reads the five marks as a sequence from the heart outward: fear at His mention, growth at His word, reliance, prayer and spending, and takes 'in truth' as the Quran's distinction between faith claimed and faith lived. He notes that faith can increase, which settles a theological dispute in the Quran's own words.",q:"Does anything happen in my chest when Allah's name is said?",k:"Real believers feel something in their heart when they hear Allah's name, and their faith grows every time they hear the Quran."},
{s:13,f:11,t:11,n:"Ar-Ra'd 11, until they change what is in themselves",sum:"Each person has guardians before and behind, protecting him by Allah's command. Allah does not change the condition of a people until they change what is in themselves; and when Allah intends harm for a people there is no turning it back.",mz:"Al-Mizan reads the law in this verse together with 8:53: a blessing is withdrawn only after the inner state that deserved it has changed, so that decline is never arbitrary. He notes that the verse states the rule for loss; the parallel rule for gain is stated elsewhere and holds for communities as well as persons.",q:"What has changed in me over the last year, and what has changed around me?",k:"Allah does not take away a good thing from people until they change on the inside. So keep your inside good."},
{s:13,f:28,t:29,n:"Ar-Ra'd 28–29, hearts find rest",sum:"Those who believe and whose hearts find rest in the remembrance of Allah; surely in the remembrance of Allah hearts find rest. Those who believe and do good have blessedness and a beautiful return.",mz:"Al-Mizan explains why remembrance, and nothing else, settles the heart: the heart is restless because it seeks something that will not fail it, and only Allah does not fail. He reads the verse as answering the disbelievers' demand for a sign in the preceding verses: the believer already has the sign, inside.",q:"What do I reach for when my heart is restless, before I reach for Allah?",k:"Your heart feels calm when you remember Allah. Nothing else can make it feel that way for long."},
{s:16,f:125,t:128,n:"An-Nahl 125–128, call with wisdom",sum:"Call to your Lord's way with wisdom and good counsel, and argue with them in the best way; your Lord knows best who strays and who is guided. If you punish, do so as you were punished; but if you are patient, it is better. Be patient, and your patience is only through Allah; do not grieve over them. Allah is with those who are God-conscious and those who do good.",mz:"Al-Mizan reads the three methods as addressed to three kinds of listener: wisdom for those who think, good counsel for those who feel, and the best argument for those who contend. He notes that even the argument must be 'the best', which rules out winning by humiliation, and that the surah ends with the Prophet's own patience as the method behind the methods.",q:"Which of the three ways do I use with my own children, and which do they need?",k:"When you tell people about Allah, be wise, be kind and argue nicely. Allah is with people who are patient and do good."},
{s:17,f:78,t:84,n:"Al-Isra 78–84, from the sun's decline to the praised station",sum:"Keep prayer from the sun's decline to the darkness of night, and the Quran of dawn, which is witnessed. Stand part of the night with it as an extra for you; your Lord may raise you to a praised station. Pray for a true entry and a true exit. Truth has come and falsehood has vanished. We send down of the Quran what is healing and mercy for the believers. Everyone acts after his own manner.",mz:"Al-Mizan reads 78 as covering the five prayers in one sentence: the four from midday to night, then the dawn prayer named separately because the angels of night and day witness it. He takes the night prayer as a duty specific to the Prophet and 'the praised station' as the intercession, and reads 'healing' as the Quran's effect on the diseases of the heart and 'everyone acts after his own manner' as the Quran's word for character.",q:"Is the dawn prayer, the witnessed one, the one I keep best or worst?",k:"Allah told the Prophet when to pray, and that the morning prayer is special because angels come to watch it. The Quran is medicine for the heart."},
{s:20,f:114,t:114,n:"Ta-Ha 114, my Lord, increase me in knowledge",sum:"Exalted is Allah, the true King. Do not hurry with the Quran before its revelation to you is completed, and say: my Lord, increase me in knowledge.",mz:"Al-Mizan notes that the only increase the Prophet is told to ask for is knowledge, and reads the instruction not to hurry as a lesson in receiving: the Quran is taken in slowly, as it comes. He connects the verse to 75:16, where the same hurry is corrected, and takes 'knowledge' here to mean knowledge of the Book itself.",q:"What did I ask Allah to give me more of today?",k:"The Prophet was taught one special dua: 'My Lord, give me more knowledge.' You can say it before school."},
{s:21,f:30,t:33,n:"Al-Anbiya 30–33, the heavens and earth were joined",sum:"Do the disbelievers not see that the heavens and the earth were one mass and We split them, and made every living thing from water? We set mountains so the earth would not shake, and passes as roads; We made the sky a protected roof, yet they turn from its signs. He created night and day, the sun and the moon, each swimming in an orbit.",mz:"Al-Mizan reads the joined mass and its splitting as a statement about origins that the listener is asked to see with the eye of reason, and refuses to tie it to any one scientific picture while allowing it to be read with the cosmology of each age. He takes 'every living thing from water' literally, and 'each swimming in an orbit' as the Quran's own description of celestial motion.",q:"Which sign of the four named here have I looked at this week?",k:"Allah says the sky and the earth were once one thing and He split them, and that every living thing is made from water. The sun and moon swim in space like fish."},
{s:24,f:30,t:31,n:"An-Nur 30–31, lowering the gaze",sum:"Tell the believing men to lower their gaze and guard their chastity; that is purer for them. Tell the believing women to lower their gaze, guard their chastity and not display their adornment except what appears, to draw their covers over their chests, and not to show their adornment except to their husbands and the near relatives listed. Turn to Allah together, believers, that you may succeed.",mz:"Al-Mizan reads the command to men first, and the same words for women, so that modesty is a shared duty before it is a dress code; the details of the women's verse follow because their adornment is what the law has to define. He takes 'what appears' as the face and hands, following the narrations from the Imams, and reads the closing 'turn to Allah together' as the reason: the rules protect a community, not a sex.",q:"Where do my eyes go when I am bored, and what would change if I lowered them?",k:"Allah tells boys and men first, then girls and women, to look away from what is not theirs to look at. Modesty is for everyone."},
{s:29,f:45,t:45,n:"Al-Ankabut 45, prayer restrains",sum:"Recite what has been revealed to you of the Book and keep prayer; prayer restrains from indecency and wrong, and the remembrance of Allah is greater. Allah knows what you do.",mz:"Al-Mizan reads 'restrains' as the nature of prayer, not a promise about every prayer: a prayer that does not restrain is lacking as prayer. He discusses 'the remembrance of Allah is greater' and prefers the reading that Allah's remembrance of His servant is greater than the servant's remembrance of Him, which is what prayer brings about.",q:"What did my last prayer stop me from doing?",k:"Real prayer keeps you away from bad things. And when you remember Allah, He remembers you, and that is even bigger."},
{s:29,f:69,t:69,n:"Al-Ankabut 69, We guide those who strive",sum:"Those who strive in Us, We will surely guide them to Our ways; and Allah is with those who do good.",mz:"Al-Mizan reads 'strive in Us', not 'for Us', as striving in the matter of Allah, whatever form it takes, and the promise as a law: effort toward Him is met with guidance into the many ways that lead to Him. He takes the plural 'ways' as the diversity of paths within the one straight path, and 'Allah is with the doers of good' as the surah's last word on its opening question about being tested.",q:"What am I striving at that Allah could count as 'in Him'?",k:"If you try hard for Allah, Allah promises to show you the way. He is with people who do good."},
{s:33,f:21,t:21,n:"Al-Ahzab 21, the beautiful example",sum:"There is for you in the Messenger of Allah a beautiful example, for whoever hopes for Allah and the Last Day and remembers Allah much.",mz:"Al-Mizan reads the verse in its place in the Battle of the Trench: the Prophet dug, went hungry and stood firm with the believers, and the example is of that, not only of ritual. He notes the three conditions on the one who takes the example, hope in Allah, hope in the Last Day and much remembrance, as the inner state that makes following possible.",q:"In what hard situation this week could I ask what the Prophet did in his?",k:"The Prophet is the best example. When things are hard, ask: what did he do? He stayed patient and kept working."},
{s:33,f:35,t:35,n:"Al-Ahzab 35, the ten qualities, men and women",sum:"Muslim men and Muslim women, believing men and believing women, obedient, truthful, patient, humble, charitable, fasting, chaste, and those who remember Allah much, men and women: Allah has prepared for them forgiveness and a great reward.",mz:"Al-Mizan records that the verse came after the women asked why the Quran addressed men, and reads the ten paired qualities as the Quran's statement that the road and its reward are identical for both. He takes the order as a progression from submission to remembrance, with 'much remembrance' last because it is the state the others produce.",q:"Of the ten, which two are strongest in Uzma and which two in me?",k:"Allah lists ten good things and says them for men and for women, both. Boys and girls get exactly the same reward for being good."},
{s:33,f:70,t:71,n:"Al-Ahzab 70–71, a straight word",sum:"O believers, be God-conscious and speak a straight word; He will set right your deeds and forgive your sins. Whoever obeys Allah and His Messenger has won a great victory.",mz:"Al-Mizan reads 'a straight word' as speech that matches the truth and the heart at once, and notes the order: straight speech first, then Allah sets the deeds right, so that honesty in words is the root of a sound life. He takes 'great victory' as the surah's summary term for the believers' outcome.",q:"What did I say today that was not quite straight?",k:"Say things that are true and clear. When your words are straight, Allah makes your actions good too."},
{s:35,f:15,t:17,n:"Fatir 15–17, you are the needy ones",sum:"O people, you are the ones in need of Allah, and Allah is the Self-Sufficient, the Praised. If He willed, He could remove you and bring a new creation; that is not hard for Him.",mz:"Al-Mizan reads 'the needy' with the definite article as the human's definition: not needy in some things, but need itself in relation to Allah, who alone is rich. He connects the verse with the surah's opening on mercy that none withholds: the needy are provided for by the One whose richness is matched by praise.",q:"In what part of my life do I pretend not to need Allah?",k:"We need Allah for everything, even for the next breath. He needs nothing from anybody."},
{s:39,f:9,t:10,n:"Az-Zumar 9–10, are those who know equal",sum:"Is one who worships through the night, prostrating and standing, fearing the Hereafter and hoping for his Lord's mercy, like the other? Say: are those who know equal to those who do not know? Only people of understanding take heed. Say: My servants who believe, fear your Lord; those who do good in this world have good, and Allah's earth is wide; the patient will be paid their reward without measure.",mz:"Al-Mizan reads the night worshipper and the knower as one person described twice, so that knowledge in the Quran's sense is what produces fear and hope and standing at night. He takes 'Allah's earth is wide' as the command to migrate rather than live where faith cannot be practised, and 'without measure' as the reward that patience alone earns.",q:"What do I know that has not yet changed what I do?",k:"Someone who prays at night and really knows Allah is not the same as someone who does not. Learning should change how you live."},
{s:39,f:22,t:23,n:"Az-Zumar 22–23, skins that shiver",sum:"Is one whose breast Allah has opened to Islam, so that he is on a light from his Lord, like the hard-hearted? Woe to those whose hearts are hardened against Allah's remembrance. Allah has sent down the best narration, a Book consistent and paired, at which the skins of those who fear their Lord shiver; then their skins and hearts soften to Allah's remembrance.",mz:"Al-Mizan reads 'consistent and paired' as the Quran describing its own form: its parts resemble each other and its themes come in pairs, promise and warning, so that one part explains another. He takes the shiver and then the softening as the two stages of the Quran's effect on a living heart, fear first and then rest.",q:"When did a verse last give me goosebumps?",k:"When people who love Allah hear the Quran, they get goosebumps, and then their hearts go soft and calm."},
{s:40,f:60,t:60,n:"Ghafir 60, call Me and I will answer",sum:"Your Lord says: call on Me and I will answer you. Those who are too proud to worship Me will enter Hell humbled.",mz:"Al-Mizan reads 'call Me' as a command and 'I will answer' as an unconditional promise, and then explains the condition hidden in the words: a real call, to Allah alone, from a heart that means it. He notes that the verse calls dua 'worship' in its second half, so refusing to ask is a form of pride.",q:"What have I been too proud to ask Allah for?",k:"Allah says: ask Me, I will answer. People who are too proud to ask Him will be sorry."},
{s:41,f:30,t:36,n:"Fussilat 30–36, those who stand firm",sum:"Those who say 'our Lord is Allah' and then stand firm, the angels descend on them: do not fear or grieve, rejoice in the Garden you were promised; we are your friends in this life and the next. Who speaks better than one who calls to Allah, does right and says 'I am of the Muslims'? Good and evil are not equal; repel evil with what is better and your enemy becomes a warm friend. None attains this but the patient and the greatly fortunate. If Satan stirs you, seek refuge in Allah.",mz:"Al-Mizan reads istiqama, standing firm, as the whole of the religion after its first sentence, and the angels' descent as beginning at death and continuing. He takes 'repel with what is better' as a law of souls, not a tactic, and explains why only the patient attain it: answering evil with good is a long effort against one's own first reaction.",q:"Who is my enemy this month, and what is 'the better' I could answer with?",k:"If you say 'Allah is my Lord' and keep going straight, angels become your friends. Answer bad with good and enemies turn into friends."},
{s:46,f:15,t:16,n:"Al-Ahqaf 15–16, the prayer at forty",sum:"We enjoined on the human kindness to his parents: his mother carried him in hardship and bore him in hardship, thirty months of carrying and weaning. When he reaches full strength and forty years, he says: my Lord, let me be grateful for Your favour on me and my parents, let me do good that pleases You, and set right my descendants; I turn to You and I am of the Muslims. From those We accept the best of what they did and overlook their faults.",mz:"Al-Mizan reads the verse as the human life in one arc: carried, weaned, grown, and at forty turned to a prayer that looks back to parents and forward to children. He notes that gratitude is asked for as a gift, 'let me be grateful', and that 'set right my descendants' is the prayer of the one who has understood that his own righteousness is incomplete without theirs.",q:"At thirty-eight, which line of the forty-year prayer am I already saying?",k:"Your mother carried you and fed you with difficulty. A good grown-up thanks Allah for his parents and asks Allah to make his children good."},
{s:50,f:16,t:18,n:"Qaf 16–18, nearer than the jugular vein",sum:"We created the human and know what his soul whispers to him, and We are nearer to him than his jugular vein. Two receivers sit on his right and left, and he utters no word without a watcher ready.",mz:"Al-Mizan reads the nearness as Allah's knowledge and presence beyond all mediation, nearer than the vein that carries life itself, and takes the two angels as real recorders whose writing is the book opened on the Day. He notes that 'no word' sets the standard: speech is the first thing recorded, before deeds.",q:"If every word is written, which sentence of mine today would I delete?",k:"Allah is closer to you than your own neck. Two angels write down every word you say. Make the book beautiful."},
{s:57,f:20,t:23,n:"Al-Hadid 20–23, the crop that withers, the book that was written",sum:"This life is play, diversion, adornment, boasting and rivalry in wealth and children, like rain whose growth pleases the farmers, then dries, yellows and crumbles. Race to forgiveness and a Garden as wide as the heavens and earth. No calamity strikes the earth or yourselves but it is in a book before We bring it about, so that you do not grieve over what escapes you or exult over what you are given.",mz:"Al-Mizan reads the five stages of the world's life, play to rivalry, as the ages of a human life, and the rain parable as its end. He takes 'in a book before We bring it about' as the verse's medicine for grief and pride at once: what came was written, what left was written, and neither is a verdict on you.",q:"What loss this year am I still grieving as if it had not been written?",k:"This life is like a crop that grows, goes yellow and dries. The real race is for Paradise. Whatever happens was already written, so do not be too sad or too proud."},
{s:58,f:11,t:11,n:"Al-Mujadila 11, make room",sum:"O believers, when you are told to make room in gatherings, make room; Allah will make room for you. When you are told to rise, rise; Allah raises those who believe among you, and those who were given knowledge, by degrees.",mz:"Al-Mizan reads the small courtesy of the first half and the great promise of the second as one lesson in degrees: those who make room are given room, and those with knowledge are raised above those with faith alone. He notes that the verse grades the believers by knowledge, which is the Quran's consistent measure of rank.",q:"Who did I make room for this week, in a gathering or in a decision?",k:"When you make space for others, Allah makes space for you. And Allah lifts people higher when they learn."},
{s:65,f:2,t:3,n:"At-Talaq 2–3, a way out from where you did not expect",sum:"Whoever fears Allah, He makes a way out for him and provides for him from where he did not expect. Whoever relies on Allah, He is enough for him. Allah accomplishes His purpose; He has set a measure for everything.",mz:"Al-Mizan reads the three sentences as three laws stated inside a chapter on divorce, so that the believer in the hardest domestic situation hears them first: taqwa opens a door, reliance is answered with sufficiency, and Allah's purpose is reached whatever the obstacles. He notes that 'He has set a measure for everything' means the way out comes by means, not against them.",q:"Where in my life am I waiting for a door that taqwa has not yet opened?",k:"If you are careful of Allah, He finds you a way out of every problem, from somewhere you never thought of."},
{s:66,f:6,t:6,n:"At-Tahrim 6, guard yourselves and your families",sum:"O believers, protect yourselves and your families from a Fire whose fuel is people and stones, over which are stern angels who do not disobey what Allah commands and do what they are told.",mz:"Al-Mizan reads the command as making the family the first field of responsibility after the self: the protection is by teaching, example and the habits of the house. He notes from the narrations that 'protect your family' was explained as commanding them what Allah commands and forbidding what He forbids, which is a duty before it is a feeling.",q:"What does my family learn from how I live, not from what I say?",k:"Allah tells parents to keep their children safe from the Fire by teaching them good things, and children to help by listening."},
{s:70,f:19,t:35,n:"Al-Ma'arij 19–35, the anxious human and the exception",sum:"The human was created anxious: fretful when harm touches him, withholding when good comes, except those who pray and are constant in their prayers; who keep a known share for the beggar and the deprived; who believe in the Day of Judgement and fear their Lord's punishment; who guard their chastity; who keep their trusts and promises; who stand by their testimony; and who guard their prayers.",mz:"Al-Mizan reads 'created anxious' as a description of the human's natural state and the exception as the cure, with prayer named first and last so that it frames the list. He takes 'a known share' as a fixed obligation beyond zakat, and sees in the whole passage the believer's inner steadiness built out of outward habits.",q:"Which of the eight habits of the exception do I keep most reliably?",k:"People worry a lot, but praying regularly, giving to the poor and keeping promises make the heart steady."},
{s:90,f:8,t:18,n:"Al-Balad 8–18, the steep path",sum:"Did We not give him two eyes, a tongue and two lips, and show him the two highways? He has not attempted the steep path. What is the steep path? Freeing a neck, or feeding on a day of hunger an orphan of near kin or a poor person in the dust, and then being of those who believe and counsel one another to patience and to mercy. Those are the companions of the right.",mz:"Al-Mizan reads the two highways as good and evil set before every person with the faculties to tell them apart, and the steep path as the hard climb against the self. He notes that the Quran names concrete acts, freeing and feeding, before it names faith and counsel, so that the climb is made of deeds the body does.",q:"What is the steepest good thing in front of me this week?",k:"Allah gave you eyes, a tongue and lips, and showed you the easy road and the hard good road. The hard road is feeding the hungry and freeing people."},
{s:99,f:1,t:8,n:"Az-Zalzalah, an atom's weight",sum:"When the earth is shaken with its quake and brings out its burdens, and the human says 'what is wrong with it', that Day it reports its news by your Lord's inspiration. People come out in groups to be shown their deeds. Whoever does an atom's weight of good will see it, and whoever does an atom's weight of evil will see it.",mz:"Al-Mizan reads the earth's report as its witness about what was done on it, and 'to be shown their deeds' as seeing the deeds themselves, which he takes as the embodiment of works in the Hereafter. He makes the last two verses the Quran's most exact statement of accountability: nothing is too small to be seen, in either direction.",q:"What atom's weight of good can I do before tonight?",k:"On the Last Day the earth will tell everything that happened on it. Even the tiniest good thing you did will be shown to you."},
{s:102,f:1,t:8,n:"At-Takathur, rivalry in more",sum:"Rivalry in increase distracts you until you visit the graves. No, you will come to know; again, you will come to know. If only you knew with certain knowledge; you will see the Blaze, then see it with the eye of certainty; then you will be asked that Day about the bliss.",mz:"Al-Mizan reads 'takathur' as boasting of having more, in wealth, children or standing, and 'until you visit the graves' as the race ending only at death. He distinguishes the knowledge of certainty from the eye of certainty, and reads the final question about 'the bliss' as covering every blessing, so that the asking is about gratitude, not guilt.",q:"What am I quietly competing to have more of, and with whom?",k:"Wanting more and more keeps people busy until they die. Allah will ask us whether we said thank you for what we had."},
{s:110,f:1,t:3,n:"An-Nasr, when the help of Allah comes",sum:"When Allah's help and the conquest come, and you see people entering Allah's religion in crowds, glorify your Lord with praise and ask His forgiveness; He is ever accepting of repentance.",mz:"Al-Mizan reads the surah as the announcement of the Prophet's work completed and, as the companions understood, of his approaching departure; the response commanded at the moment of victory is praise and seeking forgiveness, not celebration. He notes that the Prophet increased in 'subhanallah wa bihamdih, astaghfirullah' after it came down.",q:"What is my first reaction when something I worked for finally succeeds?",k:"When the Muslims finally won, Allah told the Prophet to say 'subhanallah' and ask forgiveness, not to show off. Success is a time to thank."},
{s:113,f:1,t:5,n:"Al-Falaq, refuge with the Lord of daybreak",sum:"Say: I seek refuge in the Lord of the daybreak from the evil of what He created, from the evil of darkness when it settles, from the evil of those who blow on knots, and from the evil of the envier when he envies.",mz:"Al-Mizan reads the four evils as coming from outside the self, with the envier last because envy is the evil most hidden in people near you, and 'the Lord of the daybreak' as the name chosen because He splits every darkness. He treats the two refuge surahs as one pair: this one against evils outside, an-Nas against the one inside.",q:"What do I say before I sleep, and who taught it to me?",k:"Before bed we say this surah: Allah, keep me safe from everything bad, from the dark, from bad magic and from jealous people."},
{s:114,f:1,t:6,n:"An-Nas, refuge from the whisperer",sum:"Say: I seek refuge in the Lord of people, the King of people, the God of people, from the evil of the retreating whisperer who whispers in the breasts of people, from jinn and from humans.",mz:"Al-Mizan reads the three names, Lord, King and God, as three reasons to seek refuge from the one evil that works inside, the whisper that retreats when Allah is remembered and returns when He is forgotten. He takes 'from jinn and from humans' as the two sources of the same whisper, so that a human friend can be a whisperer too.",q:"Whose voice is my 'whisperer' this week, and does it retreat when I remember Allah?",k:"The last surah of the Quran: Allah, protect me from the quiet bad thoughts that come from shaytan and from people. They run away when you remember Allah."},
];
